// Normalize Meta webhook payload to standard format
const entry = $input.item.json.entry?.[0];
const messaging = entry?.messaging?.[0];
const message = messaging?.message;
const sender = messaging?.sender;

if (!message || !sender) {
  return { json: { error: 'Invalid message structure', skip: true } };
}

// Determine if it's from Instagram or Facebook
const isInstagram = entry?.id?.startsWith('17') || $input.item.json.object === 'instagram';
const platform = isInstagram ? 'instagram' : 'facebook';

const normalized = {
  source: 'meta',
  platform: platform,
  conversation_id: `meta_${sender.id}_${entry?.id}`,
  sender_id: sender.id,
  sender_name: messaging?.sender?.name || 'Unknown',
  message: message.text || '',
  message_id: message.mid,
  timestamp: new Date(messaging.timestamp).toISOString(),
  is_echo: message.is_echo || false,
  attachments: message.attachments || [],
  metadata: {
    page_id: entry?.id,
    recipient_id: messaging?.recipient?.id,
    nlp: message.nlp || null,
    reply_to: message.reply_to || null
  }
};

return { json: normalized };

const data = $input.item.json;
const event = data.event;
const content = data.content || data.message || {};
const user = data.user || data.sender || {};

if (!event) {
  return { json: { error: 'Invalid event structure', skip: true } };
}

let messageText = '';
let messageType = 'text';

if (content.text) {
  messageText = content.text;
} else if (content.media_url) {
  messageText = '[Media]';
  messageType = 'media';
} else if (content.share_info) {
  messageText = '[Shared Content]';
  messageType = 'share';
}

const normalized = {
  source: 'tiktok',
  platform: 'tiktok',
  conversation_id: `tiktok_${user.open_id || user.user_id}_${data.conversation_id || Date.now()}`,
  sender_id: user.open_id || user.user_id || 'unknown',
  sender_name: user.display_name || user.nickname || 'TikTok User',
  message: messageText,
  message_id: data.message_id || data.msg_id || `tiktok_${Date.now()}`,
  message_type: messageType,
  timestamp: data.create_time ? new Date(data.create_time * 1000).toISOString() : new Date().toISOString(),
  is_echo: false,
  attachments: content.media_url ? [{ type: 'media', url: content.media_url }] : [],
  metadata: {
    event_type: event,
    conversation_id: data.conversation_id,
    avatar_url: user.avatar_url,
    follower_count: user.follower_count
  }
};

return { json: normalized };

const email = $input.item.json;
let messageText = email.text || email.snippet || '';
messageText = messageText.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

const fromEmail = email.from?.email || email.from || '';
const fromName = email.from?.name || fromEmail.split('@')[0] || 'Unknown';
const threadId = email.threadId || email.id;

const normalized = {
  source: 'gmail',
  platform: 'email',
  conversation_id: `gmail_${threadId}`,
  sender_id: fromEmail,
  sender_name: fromName,
  message: messageText,
  message_id: email.id || `gmail_${Date.now()}`,
  timestamp: email.date ? new Date(email.date).toISOString() : new Date().toISOString(),
  is_echo: false,
  attachments: (email.attachments || []).map(att => ({type: att.mimeType || 'unknown', filename: att.filename, size: att.size})),
  metadata: {
    subject: email.subject || '(No Subject)',
    thread_id: threadId,
    labels: email.labelIds || [],
    to: email.to,
    cc: email.cc,
    has_attachments: (email.attachments || []).length > 0
  }
};

return { json: normalized };

const input = $input.item.json;
const existingConversation = $('Check Duplicate').item.json;
const messageId = $('Execute Workflow Trigger').item.json.message_id;
const lastMessageId = existingConversation?.last_message_id;
const isDuplicate = lastMessageId === messageId;
const currentStage = existingConversation?.stage || 'new';
const conversationHistory = existingConversation?.history || [];

return {
  json: {
    ...$('Execute Workflow Trigger').item.json,
    is_duplicate: isDuplicate,
    current_stage: currentStage,
    conversation_exists: !!existingConversation?.conversation_id,
    conversation_history: conversationHistory,
    message_count: existingConversation?.message_count || 0
  }
};

const input = $input.item.json;
const intentResponse = $('Detect Intent (OpenAI)').item.json.message.content;

let intent;
try {
  intent = JSON.parse(intentResponse);
} catch (e) {
  intent = {intent: 'other', confidence: 0.5, entities: [], sentiment: 'neutral', requires_booking: false, requires_human: false};
}

// Guardrails
const message = input.message.toLowerCase();
const sensitiveKeywords = ['suicide', 'urgence', 'danger', 'menace', 'avocat', 'police', 'juridique'];
const containsSensitive = sensitiveKeywords.some(kw => message.includes(kw));

if (containsSensitive) {
  intent.requires_human = true;
  intent.handoff_reason = 'sensitive_content';
}

const MAX_AUTO_MESSAGES = 10;
if (input.message_count >= MAX_AUTO_MESSAGES && !intent.requires_booking) {
  intent.requires_human = true;
  intent.handoff_reason = 'max_messages_reached';
}

if (intent.sentiment === 'negative' && intent.confidence > 0.8) {
  intent.requires_human = true;
  intent.handoff_reason = 'negative_sentiment';
}

return {
  json: {
    ...input,
    intent: intent.intent,
    intent_confidence: intent.confidence,
    entities: intent.entities,
    sentiment: intent.sentiment,
    requires_booking: intent.requires_booking,
    requires_human: intent.requires_human,
    handoff_reason: intent.handoff_reason || null
  }
};

const input = $input.item.json;

const stageTransitions = {
  'new': {'greeting': 'new', 'question': 'qualified', 'booking': 'booking', 'complaint': 'qualified', 'thanks': 'new', 'other': 'new'},
  'qualified': {'greeting': 'qualified', 'question': 'qualified', 'booking': 'booking', 'complaint': 'qualified', 'thanks': 'qualified', 'other': 'qualified'},
  'booking': {'greeting': 'booking', 'question': 'booking', 'booking': 'booking', 'complaint': 'booking', 'thanks': 'closed', 'other': 'booking'},
  'closed': {'greeting': 'new', 'question': 'qualified', 'booking': 'booking', 'complaint': 'qualified', 'thanks': 'closed', 'other': 'closed'}
};

const currentStage = input.current_stage || 'new';
const intent = input.intent || 'other';
const newStage = stageTransitions[currentStage]?.[intent] || currentStage;

return {
  json: {...input, new_stage: newStage, stage_changed: newStage !== currentStage}
};

