const input = $input.item.json;
const replyText = input.reply_text || '';

// Base delay: 2-5 seconds
const baseDelay = Math.floor(Math.random() * 3000) + 2000;
// Typing delay: 50ms per char, max 10s
const typingDelay = Math.min(replyText.length * 50, 10000);
// Random variation: 0-2 seconds
const randomVariation = Math.floor(Math.random() * 2000);

const totalDelay = baseDelay + typingDelay + randomVariation;
const delaySeconds = Math.ceil(totalDelay / 1000);

return {
  json: {...input, delay_ms: totalDelay, delay_seconds: delaySeconds}
};

const input = $input.item.json;
const entities = input.entities || [];

const requiredFields = {name: null, email: null, phone: null, date: null, time: null, service: null};

for (const entity of entities) {
  if (entity.type === 'name' || entity.label === 'name') requiredFields.name = entity.value;
  if (entity.type === 'email' || entity.label === 'email') requiredFields.email = entity.value;
  if (entity.type === 'phone' || entity.label === 'phone') requiredFields.phone = entity.value;
  if (entity.type === 'date' || entity.label === 'date') requiredFields.date = entity.value;
  if (entity.type === 'time' || entity.label === 'time') requiredFields.time = entity.value;
  if (entity.type === 'service' || entity.label === 'service') requiredFields.service = entity.value;
}

if (!requiredFields.name && input.sender_name && input.sender_name !== 'Unknown') {
  requiredFields.name = input.sender_name;
}

const missingFields = Object.entries(requiredFields).filter(([key, value]) => !value).map(([key]) => key);
const isComplete = missingFields.length === 0;
const hasMinimumInfo = requiredFields.name && (requiredFields.email || requiredFields.phone);

return {
  json: {...input, booking_info: requiredFields, missing_fields: missingFields, is_complete: isComplete, has_minimum_info: hasMinimumInfo}
};

const input = $input.item.json;
const bookingInfo = input.booking_info;
const baseUrl = 'https://louna-co.com';
const params = new URLSearchParams();
if (bookingInfo.name) {
  const nameParts = bookingInfo.name.split(' ');
  params.append('prenom', nameParts[0]);
  if (nameParts.length > 1) params.append('nom', nameParts.slice(1).join(' '));
}
if (bookingInfo.email) params.append('email', bookingInfo.email);
